// @ts-check
// Sidebar for the wiremark docs site.
//
// Category labels live here (in the site), so nothing Docusaurus-specific has to
// be added to the portable ../docs folder. The items inside each category are
// AUTOGENERATED from the folder, ordered by the files' numeric prefixes
// (01-, 02-, ...), so new guides appear automatically with no edits here.

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  docsSidebar: [
    'README', // docs/README.md -> the index page, served at /
    {
      type: 'category',
      label: 'Guides',
      collapsed: false,
      items: [{ type: 'autogenerated', dirName: 'guides' }],
    },
    {
      type: 'category',
      label: 'Reference',
      collapsed: false,
      items: [{ type: 'autogenerated', dirName: 'reference' }],
    },
  ],
};

module.exports = sidebars;
